INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT145-S4-Q24$batch11$, 145, 4, 24, $batch11$Sufficient Assumption$batch11$, $batch11$Mallotech portrays itself to the public as a socially responsible company, but critics charge that employees in many of its factories work in unsanitary conditions. Unless these critics are mistaken, then, Mallotech is not accurately portraying itself to the public.$batch11$, $batch11$The argument’s conclusion follows logically if which one of the following is assumed?$batch11$, $batch11$D$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=145 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$A socially responsible company would never lie about whether its employees are working in unsanitary conditions.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$No company that conceals information from the public is socially responsible.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$Many employees in Mallotech’s factories work in unsanitary conditions.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$A socially responsible company would not have employees working in unsanitary conditions.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$Every company that is well managed is socially responsible.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Unless the critics are mistaken, Mallotech is not accurately portraying itself as socially responsible.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Critics say many Mallotech employees work in unsanitary conditions.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$If the critics are right, there are unsanitary conditions. The conclusion says that means Mallotech isn't socially responsible. The missing link is unsanitary conditions → not socially responsible.$batch11$), (3, $batch11$Goal$batch11$, $batch11$A socially responsible company would not have employees in unsanitary conditions.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$This is about lying, but the argument is about the working conditions themselves. Mallotech could be truthful about the conditions and still not be socially responsible.$batch11$), ($batch11$B$batch11$, $batch11$Nothing says Mallotech is concealing anything.$batch11$), ($batch11$C$batch11$, $batch11$This only confirms the critics. It doesn't connect unsanitary conditions to social responsibility.$batch11$), ($batch11$D$batch11$, $batch11$If the critics are right, Mallotech has unsanitary conditions, so it isn't socially responsible, so its portrayal is inaccurate.$batch11$), ($batch11$E$batch11$, $batch11$Management quality never comes up.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT145-S4-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
